<?php require_once __DIR__.'/_base.php'; $title='Users'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=post('status');if(in_array($status,['Active','Suspended']))$pdo->prepare('UPDATE users SET status=? WHERE id=? AND role="user"')->execute([$status,$id]);flash('success','User status updated.');redirect('users.php');}$q=post('q');$sql='SELECT * FROM users WHERE role="user"';$args=[];if($q){$sql.=' AND (name LIKE ? OR email LIKE ?)';$args=["%$q%","%$q%"];}$sql.=' ORDER BY created_at DESC';$st=$pdo->prepare($sql);$st->execute($args);?><h2>Users</h2><form class="mb-3"><input name="q" class="form-control" placeholder="Search users" value="<?=e($q)?>"></form><div class="service-card p-3"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($st->fetchAll() as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['email'])?></td><td><?=e($x['phone'])?></td><td><?=badge($x['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button name="status" value="<?=$x['status']==='Active'?'Suspended':'Active'?>" class="btn btn-sm btn-outline-secondary"><?=$x['status']==='Active'?'Suspend':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>